{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is negative or neutral and model overestimates (especially after recent spikes).",
    "Reduce forecast magnitude if recent history shows mean reversion toward lower values despite high sentiment.",
    "Increase forecast slightly if sentiment is positive and model underestimates, especially if recent prices are trending upward.",
    "Apply lag correction: if true outcome is higher than forecast, reduce next forecast by 5-10% to avoid overshoot.",
    "When sentiment is high and forecast is low, apply a bias correction upward by 3-5% to align with sentiment-driven momentum.",
    "Avoid overreacting to short-term volatility: if 3-5 consecutive days show high volatility, dampen forecast sensitivity to recent outliers."
  ]
}
